<script lang="ts">import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import {services} from '$lib/infra/model.js';import {infraState,infraCommand} from '$lib/infra/store';let error='',notice='';function check(service:string){try{infraCommand({type:'service-check',service});notice='Example check recorded for '+service+'. No VPS connection was made.';error='';}catch(e){error=e instanceof Error?e.message:'Check unavailable.';}}</script>
<Heading title="Services" subtitle="See the components expected on your self-hosted VPS."/>
<div class="stack"><div class="callout"><strong>Services have not been inspected.</strong><p>Live status, restarts and health checks require the Go engine. A browser cannot safely manage system services.</p></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}
<section class="card"><div class="row between wrap"><h3>System services</h3><a href="/server" class="btn secondary small">Server overview</a></div>{#each services as service}<div class="setting-row"><div class="row"><span class="icon-box"><Icon name={service[0]==='Docker'?'Containers':service[0]==='Mail server'?'Email':service[0]==='PostgreSQL'?'Databases':'Services'}/></span><div><strong>{service[0]}</strong><small style="display:block">{service[1]}</small></div></div><div class="row wrap"><small class="muted">{service[0]==='Mail server'?'Not configured':'Not checked'}</small><button class="btn secondary small" on:click={()=>check(service[0])}>Preview check</button></div></div>{/each}</section>
{#if $infraState.serviceEvents.length}<section class="card"><h3>Recent service previews</h3>{#each $infraState.serviceEvents.slice(0,8) as e}<div class="setting-row"><span>{e.label}</span><small>{new Date(e.at).toLocaleString()}</small></div>{/each}</section>{/if}
<div class="grid2"><a class="card feature" href="/containers" style="text-decoration:none"><Icon name="Containers"/><span><strong>Application containers</strong><small>Project processes and sample controls</small></span></a><a class="card feature" href="/certificates" style="text-decoration:none"><Icon name="Certificates"/><span><strong>Certificates</strong><small>HTTPS configuration previews</small></span></a></div></div>
